(7175072, 1102324, 114285, '<td valign="top">Stunning, gorgeous, and makes me wonder why I didn''t enter my bird shot as well!</td>', 'Stunning, gorgeous, and makes me wonder why I didn''t enter my bird shot as well!', '2014-02-12 00:17:22.000000', NULL, 1),
(7175073, 1102340, 114285, '<td valign="top">Ha, how cute is that, I nearly missed it :)</td>', 'Ha, how cute is that, I nearly missed it :)', '2014-02-12 00:18:04.000000', NULL, 1),
(7175074, 1102307, 30861, '<td valign="top">I think you''re hurting yourself with the really heavy letterboxing here, Richard. The image feels cramped and leaden to me, squeezed, laboring. It''s a lovely image regardless, I think your processing is reaching much higher levels of intensity lately.</td>', 'I think you''re hurting yourself with the really heavy letterboxing here, Richard. The image feels cramped and leaden to me, squeezed, laboring. It''s a lovely image regardless, I think your processing is reaching much higher levels of intensity lately.', '2014-02-12 00:18:50.000000', NULL, 1),
(7175085, 1102318, 114285, '<td valign="top">Sooooooo very clever, I suspect the blue goes to you :)</td>', 'Sooooooo very clever, I suspect the blue goes to you :)', '2014-02-12 00:29:34.000000', NULL, 1),
(7175096, 1102315, 16148, '<td valign="top">The combination of lines and dots reminds me of a Kandinsky.   Lovely!</td>', 'The combination of lines and dots reminds me of a Kandinsky.   Lovely!', '2014-02-12 00:57:05.000000', NULL, 1),
(7175097, 1102324, 16148, '<td valign="top">Brilliant!  Could this be Portland?  Hope this does well.</td>', 'Brilliant!  Could this be Portland?  Hope this does well.', '2014-02-12 00:58:14.000000', NULL, 1),
