(7178288, 1102096, 152252, '<td valign="top">In my top 3. Beautiful.</td>', 'In my top 3. Beautiful.', '2014-02-18 06:38:20.000000', NULL, 1),
(7178290, 1102318, 152252, '<td valign="top">Dude, you are seriously on fire, and I guess I won''t repeat that more often this year because it will get boring :) I love how the keys are aligned just perfect. Looks super classy in B&amp;W.</td>', 'Dude, you are seriously on fire, and I guess I won''t repeat that more often this year because it will get boring :) I love how the keys are aligned just perfect. Looks super classy in B&W.', '2014-02-18 06:38:24.000000', NULL, 1),
(7178291, 1101969, 152252, '<td valign="top">Beautiful tones in this one. Very interesting.</td>', 'Beautiful tones in this one. Very interesting.', '2014-02-18 06:39:16.000000', NULL, 1),
(7178330, 1101637, 61396, '<td valign="top">outstanding puzzle</td>', 'outstanding puzzle', '2014-02-18 10:06:55.000000', NULL, 1),
(7178331, 1102254, 61396, '<td valign="top">nice twist</td>', 'nice twist', '2014-02-18 10:07:49.000000', NULL, 1),
(7178333, 1102012, 61396, '<td valign="top">+1 for the multiple interrupted rhythms</td>', '+1 for the multiple interrupted rhythms', '2014-02-18 10:12:05.000000', NULL, 1),
(7178334, 1102343, 61396, '<td valign="top">cool. I was thinking this is water at first glance.</td>', 'cool. I was thinking this is water at first glance.', '2014-02-18 10:16:47.000000', NULL, 1),
(7178341, 1102287, 144271, '<td valign="top">Very interesting patterns</td>', 'Very interesting patterns', '2014-02-18 10:32:23.000000', NULL, 1),
(7178343, 1101907, 144271, '<td valign="top">Wonderful leading lines.</td>', 'Wonderful leading lines.', '2014-02-18 10:33:08.000000', NULL, 1),
(7178344, 1102286, 144271, '<td valign="top">Lovely details and sharpness</td>', 'Lovely details and sharpness', '2014-02-18 10:33:30.000000', NULL, 1),
(7178346, 1102299, 144271, '<td valign="top">Perfect for this challenge.  One of the best</td>', 'Perfect for this challenge.  One of the best', '2014-02-18 10:34:35.000000', NULL, 1),
(7178347, 1102203, 144271, '<td valign="top">The shadows make a perfect rhythmic pattern</td>', 'The shadows make a perfect rhythmic pattern', '2014-02-18 10:35:11.000000', NULL, 1),
(7178355, 1102307, 144271, '<td valign="top">Beautiful</td>', 'Beautiful', '2014-02-18 10:51:56.000000', NULL, 1),
(7178363, 1102346, 173844, '<td valign="top">Beautiful picture that has multiple rhythms ---  the fence, the clouds and the geese principally, but the entire image is a rhythmic tour de force.  Even so, there''s a great sense of peacefulness.  I also like how the sun hits the fence slats that are facing it.  My personal favorite.</td>', 'Beautiful picture that has multiple rhythms ---  the fence, the clouds and the geese principally, but the entire image is a rhythmic tour de force.  Even so, there''s a great sense of peacefulness.  I also like how the sun hits the fence slats that are facing it.  My personal favorite.', '2014-02-18 11:15:11.000000', NULL, 1),
(7178366, 1102298, 173844, '<td valign="top">Perfect title for this busily syncopated photo -- the cars -- and the more sedate rhythms of the symmetric lines of buildings and streetlamps.  Very enjoyable viewing.  Black and white choice only emphasizes the rhythms.  Excellent.</td>', 'Perfect title for this busily syncopated photo -- the cars -- and the more sedate rhythms of the symmetric lines of buildings and streetlamps.  Very enjoyable viewing.  Black and white choice only emphasizes the rhythms.  Excellent.', '2014-02-18 11:30:58.000000', NULL, 1),
(7178368, 1102002, 173844, '<td valign="top">Simple, very appealing image that winningly joins disparate elements -- fence and footsteps -- together.  Very, very nice.  The snow looks like ice cream flecked with vanilla bean particles.</td>', 'Simple, very appealing image that winningly joins disparate elements -- fence and footsteps -- together.  Very, very nice.  The snow looks like ice cream flecked with vanilla bean particles.', '2014-02-18 11:44:48.000000', NULL, 1),
(7178371, 1101963, 173844, '<td valign="top">Lovely image of, at first sight, sparkling icicles.  Then as you linger you notice the rhythms above them of decorative teeth and waves.  The graininess of the house elements nicely brings out the crystalline icicles.  Wonderfully observed.</td>', 'Lovely image of, at first sight, sparkling icicles.  Then as you linger you notice the rhythms above them of decorative teeth and waves.  The graininess of the house elements nicely brings out the crystalline icicles.  Wonderfully observed.', '2014-02-18 11:55:13.000000', NULL, 1),
(7178377, 1102298, 58634, '<td valign="top">What a view! Excellent composition! It draw my eyes immediately to this photograph and its a feast to the eyes.</td>', 'What a view! Excellent composition! It draw my eyes immediately to this photograph and its a feast to the eyes.', '2014-02-18 12:40:24.000000', NULL, 1),
(7178378, 1102337, 58634, '<td valign="top">Beautiful colors. That red is superb.</td>', 'Beautiful colors. That red is superb.', '2014-02-18 12:40:40.000000', NULL, 1),
(7178387, 1102002, 127021, '<td valign="top">i like this quite a bit</td>', 'i like this quite a bit', '2014-02-18 13:22:00.000000', NULL, 1),
(7178414, 1102201, 173844, '<td valign="top">Harshly lit tripled model makes for a compelling and unusual image.  Looks like a row of caryatids.</td>', 'Harshly lit tripled model makes for a compelling and unusual image.  Looks like a row of caryatids.', '2014-02-18 14:36:33.000000', NULL, 1),
(7178418, 1102322, 173844, '<td valign="top">Swooping rhythm of curved lines with straight line accompaniment, tied together with blues, greens and some red.  Visual music.  I''d bet this doesn''t look half as good in the daytime.  Well-observed.</td>', 'Swooping rhythm of curved lines with straight line accompaniment, tied together with blues, greens and some red.  Visual music.  I''d bet this doesn''t look half as good in the daytime.  Well-observed.', '2014-02-18 14:45:29.000000', NULL, 1),
(7178420, 1101638, 173844, '<td valign="top">I marked this image high because I find it beautiful.  It has a fine pattern, movement and composition, but I don''t see it as rhythmic.  Should I then have not credited it as highly as I did?  Maybe I''m just undiscerning or too rigid.</td>', 'I marked this image high because I find it beautiful.  It has a fine pattern, movement and composition, but I don''t see it as rhythmic.  Should I then have not credited it as highly as I did?  Maybe I''m just undiscerning or too rigid.', '2014-02-18 15:06:29.000000', NULL, 1),
(7178422, 1102096, 19825, '<td valign="top">An interesting scene.</td>', 'An interesting scene.', '2014-02-18 15:16:10.000000', NULL, 1),
(7178423, 1102315, 19825, '<td valign="top">Lovely contrasts.</td>', 'Lovely contrasts.', '2014-02-18 15:16:33.000000', NULL, 1),
(7178424, 1102298, 19825, '<td valign="top">Fascinating cityscape.</td>', 'Fascinating cityscape.', '2014-02-18 15:16:59.000000', NULL, 1),
(7178426, 1101969, 173844, '<td valign="top">Works beautifully as abstract art, especially since I don''t know what I''m looking at beyond reflections in water.  And it''s harmoniously rhythmic, too.<br/>The title is quite apt; it also reminds me of i ching figures.</td>', 'Works beautifully as abstract art, especially since I don''t know what I''m looking at beyond reflections in water.  And it''s harmoniously rhythmic, too.The title is quite apt; it also reminds me of i ching figures.', '2014-02-18 15:18:35.000000', NULL, 1),
(7178431, 1102254, 173844, '<td valign="top">Only upon twisting my head 90 degrees did I demystify this delightfully confusing image.  This orientation is so much more interesting.  The rhythm is certainly there, with the reflection offering a variation of the actual.  Enchanting.</td>', 'Only upon twisting my head 90 degrees did I demystify this delightfully confusing image.  This orientation is so much more interesting.  The rhythm is certainly there, with the reflection offering a variation of the actual.  Enchanting.', '2014-02-18 15:26:45.000000', NULL, 1),
(7178432, 1101907, 173844, '<td valign="top">Rhythm on a monumental scale, almost overwhelmingly so.  Everything is working together here.  This is pleasingly triumphant.</td>', 'Rhythm on a monumental scale, almost overwhelmingly so.  Everything is working together here.  This is pleasingly triumphant.', '2014-02-18 15:34:45.000000', NULL, 1),
(7178434, 1102299, 173844, '<td valign="top">Like notes on musical staffs.  Strongly rhythmic pattern on a calm field of green and beige.  Very pleasing.</td>', 'Like notes on musical staffs.  Strongly rhythmic pattern on a calm field of green and beige.  Very pleasing.', '2014-02-18 15:40:36.000000', NULL, 1),
(7178436, 1102327, 173844, '<td valign="top">Deceptively simple image with a powerfully rhythmic fence.  Nicely composed.  Looks a bit like piano keys.</td>', 'Deceptively simple image with a powerfully rhythmic fence.  Nicely composed.  Looks a bit like piano keys.', '2014-02-18 15:45:40.000000', NULL, 1),
(7178437, 1102303, 173844, '<td valign="top">Attractive pattern of lines and solids that must change -- rhythmically -- with the rise and fall of the wavelets.  There''s additional rhythm in the various shades of blue.  Handsome.</td>', 'Attractive pattern of lines and solids that must change -- rhythmically -- with the rise and fall of the wavelets.  There''s additional rhythm in the various shades of blue.  Handsome.', '2014-02-18 15:50:46.000000', NULL, 1),
(7178438, 1102139, 173844, '<td valign="top">A wonderfully rhythmic image that looks like abstract art, but is all the more satisfying because it''s an actual depiction of a natural object.  It looks celestial.</td>', 'A wonderfully rhythmic image that looks like abstract art, but is all the more satisfying because it''s an actual depiction of a natural object.  It looks celestial.', '2014-02-18 15:56:49.000000', NULL, 1),
(7178440, 1102300, 173844, '<td valign="top">Beautiful photo of bamboo standing in a casual rhythm.  I like how the stalks look burnished, almost metallic.  Has an almost otherworldly feel.  The only distraction is the carving on a central stalk.</td>', 'Beautiful photo of bamboo standing in a casual rhythm.  I like how the stalks look burnished, almost metallic.  Has an almost otherworldly feel.  The only distraction is the carving on a central stalk.', '2014-02-18 16:02:30.000000', NULL, 1),
